import java.nio.file.*;
import java.io.*;
import java.nio.channels.FileChannel;
import java.nio.ByteBuffer;
import static java.nio.file.StandardOpenOption.*;

public class NoRewind
{
    public static void main(String[] args) throws Exception
    {
        Path file = Paths.get("Numbers.txt");
        Files.write(file, "0123456789012345".getBytes());
        ByteBuffer out = ByteBuffer.wrap("XYZ".getBytes());
        FileChannel fc =
            (FileChannel)Files.newByteChannel(file, READ, WRITE);
        fc.position(0);
        while(out.hasRemaining())
            fc.write(out);
        fc.position(10);
        while(out.hasRemaining())
            fc.write(out);
        fc.close();
        System.out.println(Files.readAllLines(file).get(0));
        Files.deleteIfExists(file);
    }
}

