import java.nio.file.*;
import java.io.*;
import java.nio.channels.FileChannel;
import java.nio.ByteBuffer;
import static java.nio.file.StandardOpenOption.*;

public class NoRewrap
{
    public static void main(String[] args) throws Exception
    {
        Path file = Paths.get("Staff.txt");
        String sep = System.getProperty("line.separator");
        String recs = "000,       ,00.00" + sep + "001,Alvarez,18.50" + sep +
            "002,Newmann,22.25" + sep + "003,Johnson,19.75" + sep;
        Files.write(file, recs.getBytes());
        String s = "000,       ,00.00" + sep;
        final int RECSIZE = s.length();
        byte[] data = s.getBytes();
        ByteBuffer buffer = ByteBuffer.wrap(data);
        FileChannel fc = (FileChannel)Files.newByteChannel(file, READ, WRITE);
        buffer = ByteBuffer.wrap(data);
        int[] ids = {1, 3};
        for(int id : ids)
        {
            fc.position(id * RECSIZE);
            fc.read(buffer);
            s = new String(data);
            System.out.println(s.trim());
        }
        fc.close();
        Files.deleteIfExists(file);
    }
}
